package com.courseplanner.ui;

import com.courseplanner.model.*;import com.courseplanner.service.CourseGraph;
import java.awt.*;import java.awt.event.*;import java.awt.geom.*;import java.util.*;import javax.swing.*;

public class GraphPanel extends JPanel {
 private java.util.List<Course> courses=java.util.List.of(); private Map<String,Set<String>> prerequisites=Map.of(); private Map<String,ProgressStatus> progress=Map.of();
 private final Map<String,Point2D.Double> points=new LinkedHashMap<>(); private String selected=null; private Set<String> highlighted=new HashSet<>(); private Set<String> cyclicNodes=Set.of(); private double zoom=1,panX=0,panY=0; private Point drag;
 public GraphPanel(){setBackground(Color.WHITE);setPreferredSize(new Dimension(900,570));setBorder(BorderFactory.createLineBorder(new Color(226,232,240)));addMouseWheelListener(e->{zoom=Math.max(.55,Math.min(1.8,zoom*(e.getWheelRotation()<0?1.1:.9)));repaint();});addMouseListener(new MouseAdapter(){public void mousePressed(MouseEvent e){drag=e.getPoint();String hit=hit(e.getPoint());if(hit!=null){selected=hit;repaint();}}});addMouseMotionListener(new MouseMotionAdapter(){public void mouseDragged(MouseEvent e){if(drag!=null){panX+=e.getX()-drag.x;panY+=e.getY()-drag.y;drag=e.getPoint();repaint();}}});}
 public void setData(java.util.List<Course> c,Map<String,Set<String>> p,Map<String,ProgressStatus> s){courses=c;prerequisites=p;progress=s;try{cyclicNodes=new CourseGraph(c.stream().map(Course::getId).toList(),p).cycleNodes();}catch(Exception ignored){cyclicNodes=Set.of();}layoutNodes();repaint();}
 public void setHighlightedPath(java.util.List<String> path){highlighted=new HashSet<>(path);repaint();}
 private void layoutNodes(){points.clear();int n=courses.size();if(n==0)return;double cx=430,cy=270,rx=Math.max(230,n*24),ry=Math.max(145,n*14);for(int i=0;i<n;i++){double a=-Math.PI/2+2*Math.PI*i/n;points.put(courses.get(i).getId(),new Point2D.Double(cx+rx*Math.cos(a),cy+ry*Math.sin(a)));}}
 private Point2D.Double screen(Point2D.Double p){return new Point2D.Double(p.x*zoom+panX,p.y*zoom+panY);}
 private String hit(Point p){for(var e:points.entrySet()){Point2D q=screen(e.getValue());if(q.distance(p)<43*zoom)return e.getKey();}return null;}
 @Override protected void paintComponent(Graphics raw){super.paintComponent(raw);Graphics2D g=(Graphics2D)raw.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.translate(panX,panY);g.scale(zoom,zoom);
  // prerequisite edges are drawn prerequisite -> dependent
  for(var e:prerequisites.entrySet()){Point2D.Double target=points.get(e.getKey());if(target==null)continue;for(String pre:e.getValue()){Point2D.Double src=points.get(pre);if(src!=null)drawArrow(g,src,target,pre,e.getKey());}}
  for(Course c:courses){Point2D.Double p=points.get(c.getId());if(p==null)continue;ProgressStatus st=progress.getOrDefault(c.getId(),ProgressStatus.PENDING);Color fill=cyclicNodes.contains(c.getId())?Theme.RED:st==ProgressStatus.COMPLETED?Theme.GREEN:st==ProgressStatus.ENROLLED?Theme.BLUE:(isEligible(c.getId())?new Color(55,125,220):Theme.ORANGE);if((selected!=null&&(selected.equals(c.getId())||isRelated(selected,c.getId())))||highlighted.contains(c.getId()))g.setStroke(new BasicStroke(3));else g.setStroke(new BasicStroke(1.4f));g.setColor(fill);g.fillRoundRect((int)p.x-52,(int)p.y-25,104,50,16,16);g.setColor(selected!=null&&selected.equals(c.getId())?Color.BLACK:fill.darker());g.drawRoundRect((int)p.x-52,(int)p.y-25,104,50,16,16);g.setColor(Color.WHITE);g.setFont(new Font("SansSerif",Font.BOLD,11));FontMetrics fm=g.getFontMetrics();String label=c.getId();g.drawString(label,(int)p.x-fm.stringWidth(label)/2,(int)p.y+4);g.setFont(new Font("SansSerif",Font.PLAIN,9));String nm=c.getName();if(nm.length()>17)nm=nm.substring(0,16)+"…";fm=g.getFontMetrics();g.drawString(nm,(int)p.x-fm.stringWidth(nm)/2,(int)p.y+17);}
  g.dispose();}
 private boolean isEligible(String id){for(String pre:prerequisites.getOrDefault(id,Set.of()))if(progress.getOrDefault(pre,ProgressStatus.PENDING)!=ProgressStatus.COMPLETED)return false;return true;}
 private boolean isRelated(String a,String b){return prerequisites.getOrDefault(a,Set.of()).contains(b)||prerequisites.getOrDefault(b,Set.of()).contains(a);}
 private void drawArrow(Graphics2D g,Point2D a,Point2D b,String from,String to){double dx=b.getX()-a.getX(),dy=b.getY()-a.getY(),len=Math.hypot(dx,dy);if(len<1)return;double ux=dx/len,uy=dy/len;double sx=a.getX()+ux*54,sy=a.getY()+uy*28,ex=b.getX()-ux*55,ey=b.getY()-uy*29;boolean hot=highlighted.contains(from)&&highlighted.contains(to);g.setColor(hot?Theme.BLUE:new Color(145,158,178));g.setStroke(new BasicStroke(hot?3f:1.7f));g.draw(new Line2D.Double(sx,sy,ex,ey));double ang=Math.atan2(ey-sy,ex-sx),size=9;Path2D head=new Path2D.Double();head.moveTo(ex,ey);head.lineTo(ex-size*Math.cos(ang-.45),ey-size*Math.sin(ang-.45));head.lineTo(ex-size*Math.cos(ang+.45),ey-size*Math.sin(ang+.45));head.closePath();g.fill(head);}
}
